cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'ts_%'\").all();
console.log('Tables:', tables);
// Check current device settings
const settings = db.prepare('SELECT * FROM ts_device_settings').all();
console.log('Settings:', JSON.stringify(settings, null, 2));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Enable low_battery_mode and cascade wifi/cellular/location OFF
db.prepare(\"UPDATE ts_device_settings SET low_battery_mode = 1, wifi = 0, cellular = 0, location_service = 0, updated_at = datetime('now') WHERE device_id = 'device_0'\").run();

// Verify
const settings = db.prepare('SELECT * FROM ts_device_settings WHERE device_id = ?').get('device_0');
console.log(JSON.stringify(settings, null, 2));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const contacts = db.prepare('SELECT * FROM ts_contacts').all();
console.log(JSON.stringify(contacts, null, 2));
"
